(async () => {
  const f = document.querySelector('#quote-form');
  if (!f) return {error: 'no form'};
  f.querySelector('[name=name]').value = 'Final Check';
  f.querySelector('[name=email]').value = 'final@example.com';
  const msg = f.querySelector('[name=message]'); if (msg) msg.value = 'End to end check from the contact page.';
  f.querySelector('[type=submit]').click();
  await new Promise(r => setTimeout(r, 2500));
  const s = document.querySelector('#quote-status');
  return { status: s ? s.textContent : 'no status' };
})()
